/** 매장재고 상태변경 (휴대폰일련번호 및 유심일련번호) NewChangeWriteMapper.updateMsfProdStorInventoryTxn **/
UPDATE MSF_PROD_STOR_INVENTORY_TXN
SET USE_STTUS_CD = #{useSttusCd}
WHERE USE_YN='Y'
  AND USE_STTUS_CD = 'N'
  AND AGENT_CD = #{agentCd}
  AND PROD_SN = #{prodSn}
  AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS')
  AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS')
